from datetime import datetime, timezone

settings = api.extension.settings() or {}
product = settings.get("product_name") or "your product"

counts = {"high": 0, "medium": 0, "low": 0, "untriaged": 0}
open_count = 0
cursor = None
for _ in range(10):
    args = {"type_slug": "customer_feedback", "limit": 200}
    if cursor is not None:
        args["cursor"] = cursor
    page = api.records.list(**args) or {}
    for r in page.get("records", []):
        fields = r.get("fields") or r.get("values") or r
        if str(fields.get("status") or "new") == "closed":
            continue
        open_count += 1
        sev = str(fields.get("severity") or "")
        counts[sev if sev in counts else "untriaged"] += 1
    cursor = page.get("nextCursor")
    if cursor is None:
        break

today = datetime.now(timezone.utc).date().isoformat()
title = f"Feedback digest {today}"
summary = (
    f"{open_count} open feedback item(s) for {product}: "
    f"{counts['high']} high, {counts['medium']} medium, {counts['low']} low, {counts['untriaged']} not yet triaged."
)
existing = api.workq.list(search=title) or []
if not any(isinstance(i, dict) and i.get("title") == title for i in existing):
    api.workq.create(title=title, scope="org", priority="low", description=summary)
